        '차령(최초 등록 후 경과연수)이 3년 미만이면 감경 없이 기준세액 그대로 적용하고, 3년차부터는 매년 5%포인트씩 감경률이 늘어나 12년차 이상이면 최대 50%까지 감경합니다.',
        '기준세액에 (1 − 감경률)을 곱해 자동차세를 계산합니다.',
