    glossary: [
      { term: '10년 합산과세', definition: '동일인으로부터 10년 이내 받은 증여재산을 모두 더해 과세표준을 계산하는 원칙입니다.' },
      { term: '혼인·출산 증여재산공제', definition: '2024년 신설된 공제로, 직계존속→직계비속 증여에 한해 혼인·출산 요건 충족 시 추가로 최대 1억원까지 공제됩니다.' },
      { term: '세대생략증여', definition: '조부모→손자녀 등 한 세대를 건너뛰는 증여로 산출세액에 30~40%가 할증됩니다.' },
      { term: '증여재산공제', definition: '증여자와 수증자의 관계에 따라 10년 합산 기준으로 적용되는 공제 한도입니다.' },
      { term: '신고세액공제', definition: '신고기한(3개월) 내 자진신고하면 산출세액의 3%를 깎아주는 제도입니다.' },
    ],
    faqs: [
      { q: '혼인·출산 공제는 신랑·신부 양가에서 각각 받을 수 있나요?', a: '수증자 본인 기준으로 부모(또는 조부모)로부터 받는 증여에 적용되는 공제이므로, 신랑측·신부측 부모로부터 각각 증여받는다면 각자 별도로 적용받을 수 있습니다. 정확한 적용 여부는 국세청 홈택스나 세무사 상담으로 확인하는 것이 안전합니다.' },
      { q: '10년 합산 대상에 배우자로부터 받은 증여도 포함되나요?', a: '세법상 동일인에는 증여자의 배우자도 포함되는 것으로 해석되는 경우가 있어 합산 범위가 넓어질 수 있습니다. 이 계산기는 합산액을 직접 입력하는 방식이므로, 정확한 합산 대상은 국세청 확인이 필요합니다.' },
      { q: '세대생략증여 할증은 항상 적용되나요?', a: '아버지가 먼저 사망해 손자녀가 대습상속인이 되는 경우 등 일부 예외에는 할증이 적용되지 않습니다. 이 계산기는 일반적인 세대생략증여만 반영한 간이 계산입니다.' },
      { q: '신고기한을 넘기면 어떻게 되나요?', a: '3% 신고세액공제를 받을 수 없고, 무신고가산세 등 추가 불이익이 발생할 수 있습니다.' },
      { q: '부담부증여란 무엇이고 세금은 어떻게 계산되나요?', a: '부담부증여는 전세보증금이나 대출채무가 있는 부동산을 증여하면서 그 채무를 수증자가 함께 넘겨받는 방식입니다. 채무 인수액만큼은 유상 양도로 보아 증여자에게 양도소득세가 과세되고, 나머지(재산가액-채무액)에 대해서만 수증자에게 증여세가 부과됩니다. 배우자·직계존비속 간 부담부증여는 채무를 수증자가 실제로 갚을 능력과 상환 사실을 입증하지 못하면 채무액도 증여로 보아 전액 증여세가 과세될 수 있어 주의가 필요합니다.' },
      { q: '현금과 부동산 중 어느 쪽으로 증여하는 게 유리한가요?', a: '증여세 자체는 증여재산가액을 기준으로 동일하게 계산되지만, 부동산은 시가를 산정하기 어려운 경우 보충적 평가방법(공시가격 등)으로 평가되어 실제 시가보다 낮게 잡힐 수 있는 반면, 현금은 증여한 금액 그대로 과세됩니다. 다만 부동산 증여는 취득세(증여 취득세율 3.5~4%)가 추가로 발생하므로, 총비용은 개별 상황에 따라 달라져 일률적으로 유리하다고 말하기 어렵습니다.' },
      { q: '이미 준 증여를 취소하거나 돌려받으면 세금은 어떻게 되나요?', a: '금전이 아닌 재산을 증여받고 신고기한(3개월) 이내에 합의해서 반환하면 처음부터 증여가 없었던 것으로 보아 증여세가 부과되지 않습니다. 신고기한 후 3개월 이내에 반환하면 반환분에 대해서는 증여세가 부과되지 않지만 최초 증여에 대한 가산세는 부과될 수 있고, 그 이후에 반환하면 반환하는 것 자체도 별도의 증여로 보아 다시 과세됩니다. 금전은 반환 시점과 무관하게 반환 자체도 증여로 보므로 신고 전에 신중히 결정해야 합니다.' },
      { q: '증여세 신고 후 세무조사가 나오면 어떤 걸 확인하나요?', a: '국세청은 신고된 증여재산의 평가액이 적정한지, 신고 누락된 다른 증여재산이 없는지, 자금 출처가 명확한지(특히 미성년자·무소득자에게 고액 증여 시 자금 출처를 소급 확인) 등을 검토합니다. 특히 부동산 취득자금이나 사업 개시 자금의 출처가 불분명하면 별도의 증여세 조사(자금출처조사) 대상이 될 수 있습니다.' },
    ],
